# Data Pipeline Agent
# Routes data through clean / summarise / transform / analyse tasks.

def agent(inputs):
    data = inputs.get('data', '')
    task = inputs.get('task', 'analyse')
    output_format = inputs.get('output_format', 'markdown')

    # TODO: implement each task branch
    if task == 'clean':
        result = data.strip()  # replace with real cleaning logic
    elif task == 'summarise':
        result = data[:200] + '...'  # replace with LLM summarisation
    elif task == 'transform':
        result = data  # replace with transformation logic
    else:  # analyse
        result = f'Analysis of {len(data)} chars of data.'  # replace with LLM analysis

    if output_format == 'json':
        import json
        return json.dumps({'result': result})
    return result
